import {AIMessage} from '@langchain/core/messages';
import {context} from '@opentelemetry/api';
import {AsyncLocalStorageContextManager} from '@opentelemetry/context-async-hooks';
import {TracerProvider,SimpleSpanProcessor,InMemorySpanExporter} from '@opentelemetry/sdk-trace';
import {SqliteAgentRuns,SqliteAgentDefinitions,DurableAgentWorker,ConfiguredAgentOperationMetrics,createConfiguredAgentRun} from '../../dist/index.js';
const manager=new AsyncLocalStorageContextManager().enable();context.setGlobalContextManager(manager);const exporter=new InMemorySpanExporter(),provider=new TracerProvider({spanProcessors:[new SimpleSpanProcessor({exporter})]}),tracer=provider.getTracer('worker'),runs=new SqliteAgentRuns(process.env.TEST_RUNS),definitions=new SqliteAgentDefinitions(process.env.TEST_DEFINITIONS),metrics=new ConfiguredAgentOperationMetrics({authorize:()=>true}),scope={tenantId:'tenant',agentId:'agent'};let calls=0,turns=0;
try{const worker=new DurableAgentWorker({runs,definitions,workerId:'worker',leaseMs:10000,pollMs:100,authorizeStart:()=>true,tracing:{tracer,usePersistedParent:true},execute:async(run,{signal})=>{const agent=await createConfiguredAgentRun({definitions,tenantId:'tenant',agentId:'agent',expectedVersion:run.definitionVersion,bindings:[{operationId:'lookup',toolName:'lookup',description:'private-description'}],registry:{invoke:async(_operation,_input,actor)=>{if(actor.principalId!=='service')throw Error('Wrong actor');calls++;return {private:'tool-result-secret'};}},authorizeRun:()=>true,authorizeCapability:()=>true,tracing:{tracer},observeOperation:metrics.observe,createModel:()=>({invoke:async()=>++turns===1?new AIMessage({content:'',tool_calls:[{id:'call-secret',name:'lookup',args:{query:{private:'argument-secret'}},type:'tool_call'}]}):new AIMessage('output-secret')})});let last;for await(const event of agent.run({threadId:'thread-secret',runId:run.runId,messages:[{role:'user',content:'prompt-secret'}]},{signal}))last=event;return last?.type==='RUN_FINISHED'?'succeeded':'uncertain';}}),result=await worker.runOnce(scope,process.env.TEST_RUN_ID),spans=exporter.getFinishedSpans().map(span=>({name:span.name,traceId:span.spanContext().traceId,spanId:span.spanContext().spanId,parent:span.parentSpanContext?.spanId,attributes:span.attributes,events:span.events})),counts=await metrics.snapshot({tenantId:'tenant',principalId:'reader'});process.stdout.write(JSON.stringify({status:result.status,calls,turns,spans,counts}));}finally{runs.close();definitions.close();await provider.shutdown();context.disable();manager.disable();}
